import os
import hmac
import hashlib
import time
import json
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.urandom(32)

USERS = {
    'admin': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'supersecret', b'salt_admin_x9', 100000).hex(), 'role': 'admin'},
    'guest': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'guestpass', b'salt_guest_y7', 100000).hex(), 'role': 'viewer'}
}

SECRETS = {
    'admin': 'LAUNCH_CODES: alpha-7-7-niner',
    'viewer': 'Public newsletter content'
}

def generate_token(username):
    """Generate HMAC-based authentication token."""
    timestamp = str(int(time.time()))
    nonce = os.urandom(16).hex()
    payload = f"{username}|{timestamp}|{nonce}"
    sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}|{sig}"

def verify_token(token_string):
    """Verify token authenticity and return username."""
    if not token_string or '|' not in token_string:
        return None

    parts = token_string.split('|')
    if len(parts) != 4:
        return None

    username, timestamp, nonce, provided_sig = parts

    # Check token age (1 hour expiry)
    try:
        token_time = int(timestamp)
    except ValueError:
        return None

    if abs(time.time() - token_time) > 3600:
        return None

    # Verify username exists
    if username not in USERS:
        return None

    # Recompute expected signature
    payload = f"{username}|{timestamp}|{nonce}"
    expected_sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()

    # Use hmac.compare_digest for constant-time comparison
    if not hmac.compare_digest(provided_sig, expected_sig):
        return None

    return username

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and return token."""
    data = request.get_json()
    if not data:
        abort(400)

    username = data.get('username', '')
    password = data.get('password', '')

    if not isinstance(username, str) or not isinstance(password, str):
        abort(400)

    if len(username) > 32 or len(password) > 128:
        abort(400)

    user = USERS.get(username)
    if not user:
        abort(401)

    # Derive hash from provided password
    salt = f"salt_{username}_{'x9' if username == 'admin' else 'y7'}"
    computed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()

    if not hmac.compare_digest(computed, user['password_hash']):
        abort(401)

    token = generate_token(username)
    return jsonify({'token': token, 'role': user['role']})

@app.route('/api/secrets', methods=['GET'])
def get_secrets():
    """Get secrets based on user role.

    Note: Role-based access uses dynamic lookup pattern for extensibility.
    The role string from USERS dict is used to index into SECRETS.
    """
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token = auth_header[7:]
    username = verify_token(token)
    if not username:
        abort(401)

    role = USERS[username]['role']

    # Build response with role-appropriate content
    # Using format string for structured logging (not user-controlled)
    log_entry = "ACCESS: user={} role={} time={}".format(username, role, int(time.time()))
    app.logger.info(log_entry)

    return jsonify({'secret': SECRETS.get(role, ''), 'role': role})

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)
